from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_coam.common.common import LocalBasicPage
from .modals import LegalNoticeModal, WebElementManagerReloadModal


class LoginPage(LocalBasicPage):
    def __init__(self, download_dir, screenshot_dir):
        super(LoginPage, self).__init__(download_dir, screenshot_dir)

    def _insert_username(self, locator, username, timeout=60):
        self.insert_text_to_enable_element(locator, username, timeout)

    def _insert_password(self, locator, password, timeout=60):
        self.insert_text_to_enable_element(locator, password, timeout)

    def _click_login_button(self, locator, timeout=60):
        self.click_enabled_element(locator, timeout)


class CoamLoginPage(LoginPage):
    """
    A class manages login page, login function included.
    """
    _INPUT_USERNAME_XPATH = '//input[@name="userName"]'
    _INPUT_PASSWORD_XPATH = '//input[@name="password"]'
    _LOGIN_BUTTON_XPATH = '//div[@class="login-buttons"]//button[contains(text(), "Login")]'
    SESSION_LOCKED_XPATH = '//*[text()="Session locked"]'
    PASSWD_INPUT_XPATH = '//input[@id="screen-lock-password-input"]'
    LOGO_XPATH = '//*[@class="logo" and @name="Nokia"]'

    def __init__(self, download_dir=None, screenshot_dir=None):
        super(CoamLoginPage, self).__init__(download_dir, screenshot_dir)
        self.legal_notice_modal = LegalNoticeModal()
        self.reload_modal = WebElementManagerReloadModal()

    def login(self, url, username, password, timeout=60):
        """
        Login into coam bts.
        :param url: str, url to coam web
        :param username: str, username
        :param password: str, password
        :param timeout: int, timeout
        """
        self.driver.get(url)
        self._insert_username((By.XPATH, self._INPUT_USERNAME_XPATH), username, timeout)
        self._insert_password((By.XPATH, self._INPUT_PASSWORD_XPATH), password, timeout)
        self._click_login_button((By.XPATH, self._LOGIN_BUTTON_XPATH), timeout)

        self.legal_notice_modal.wait_until_legal_notice_modal_appear(timeout)
        self.legal_notice_modal.confirm()

        self.reload_modal.wait_until_login_modal_appear(timeout=6)
        self.reload_modal.confirm(timeout=6)

    def login_after_screen_lock(self, passwd, timeout=60):
        """
        Keyword for login into webem after screen lock.
        :param passwd: password for webem
        :type passwd: str
        :param timeout: timeout
        :type timeout: str or int
        """
        self.wait_for_visibility_by_xpath(self.SESSION_LOCKED_XPATH, timeout)
        self.insert_text_to_enable_element_and_enter((By.XPATH, self.PASSWD_INPUT_XPATH), passwd, timeout)
        self.wait_for_visibility_by_xpath(self.LOGO_XPATH, timeout)


class LabAccessLoginPage(LoginPage):
    _INPUT_USERNAME_XPATH = '//input[@id="username"]'
    _INPUT_PASSWORD_XPATH = '//input[@id="password"]'
    _SIGN_IN_XPATH = '//input[@type="submit"]'
    _LOGOUT_BUTTON_XPATH = '//td[@id="SignOutbg"]'

    def __init__(self, download_dir=None, screenshot_dir=None):
        super(LabAccessLoginPage, self).__init__(download_dir, screenshot_dir)

    def login(self, url, username, password, timeout=60):
        self.driver.get(url)
        self._insert_username((By.XPATH, self._INPUT_USERNAME_XPATH), username, timeout)
        self._insert_password((By.XPATH, self._INPUT_PASSWORD_XPATH), password, timeout)
        self._click_login_button((By.XPATH, self._SIGN_IN_XPATH), timeout)

        self.wait_for_visibility((By.XPATH, self._LOGOUT_BUTTON_XPATH), timeout)
        self.switch_to_coam_login_tab()


class LogoutPage(LocalBasicPage):
    """
    A class manages logout page, logout function included.
    """
    _USER_COUNT_VIEW_XPATH = '//user-account-management'
    _LOGOUT_BUTTON_XPATH = '//div[@class="user-account-view"]//ui-button[@a-text="Logout"]'

    def logout(self, click_timeout, timeout=60):
        """
        Logout from selenium_coam web.
        :param click_timeout: int, timeout to being able to click
        :param timeout: int, timeout
        """
        self.wait_until_element_is_clickable(self._USER_COUNT_VIEW_XPATH, click_timeout)
        self.click_enabled_element_after_visible((By.XPATH, self._USER_COUNT_VIEW_XPATH), timeout)
        self.wait_until_element_is_clickable(self._LOGOUT_BUTTON_XPATH, click_timeout)
        self.click_enabled_element_after_visible((By.XPATH, self._LOGOUT_BUTTON_XPATH), timeout)
        self.close_browser()
